wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

/// Bound on the tool-orchestration loop, so a model that keeps asking for
/// lookups can never spin forever inside a single `run`.
const MAX_ROUNDS: u32 = 8;

const SYSTEM: &str =
    "You are a customer-support agent. Answer the user's question using only the \
     provided knowledge and any lookups you request. Be concise and accurate.";

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input, so the question
        // is already bounded; we build the material from it and the knowledge
        // the upstream node attenuated down to this context.
        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push('\n');

        if !ctx.knowledge.is_empty() {
            prompt.push_str("Knowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        prompt.push('\n');

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    // The only tool this node's scope admits is `lookup`, served
                    // by the read-only knowledge-base handle. Any other tool the
                    // model names is one we hold no import for, so we report it
                    // back as context and let the model continue without it.
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\nLookup \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\" returned:\n");
                        if results.is_empty() {
                            prompt.push_str("- (no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        prompt.push_str("\nTool \"");
                        prompt.push_str(&req.tool);
                        prompt.push_str("\" is not available; answer without it.\n");
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "exceeded tool-call budget without a final answer".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

